// Gameplay badges keep their own symbol, size, ink and background. Only an
// Deity NFT's effective rim replaces their normal outer-ring color.
import { readDeityRingColor } from './deity-customization.js';
import { registerReadCacheInvalidator } from './read-provider.js';

const cache = new Map();
registerReadCacheInvalidator(() => cache.clear());

/** Recolor just the outer circle in a trusted, local standard badge asset. */
export function recolorDeitySymbolRing(svg, color) {
  if (!/^#[0-9a-f]{6}$/i.test(color)) throw new Error('Invalid ring color.');
  const circles = svg.match(/<circle\b[^>]*\br=(['"])35\.2\1[^>]*>/g);
  if (circles?.length !== 1 || !/\bfill=['"][^'"]+['"]/.test(circles[0])) {
    throw new Error('Standard symbol ring not found.');
  }
  const ring = circles[0].replace(/\bfill=(['"])[^'"]+\1/, `fill="${color.toLowerCase()}"`);
  return svg.replace(circles[0], ring);
}

export async function readDeitySymbolAppearance(symbolId, standardBadgeUrl) {
  if (!Number.isInteger(symbolId) || symbolId < 0 || symbolId > 31) return null;
  const key = `${symbolId}:${standardBadgeUrl}`;
  const previous = cache.get(key);
  if (previous && previous.expiresAt > Date.now()) return previous.promise;
  const entry = { expiresAt: Date.now() + 60_000, promise: null };
  entry.promise = (async () => {
    try {
      const ringColor = await readDeityRingColor(symbolId);
      if (!ringColor) return null;
      const response = await fetch(standardBadgeUrl);
      if (!response.ok) throw new Error('Could not load the standard badge.');
      const svg = recolorDeitySymbolRing(await response.text(), ringColor);
      return { src: `data:image/svg+xml,${encodeURIComponent(svg)}`, ringColor };
    } catch {
      // Failed reads retry on the next refresh; they never import NFT artwork.
      if (cache.get(key) === entry) cache.delete(key);
      return null;
    }
  })();
  cache.set(key, entry);
  return entry.promise;
}

export function invalidateDeitySymbolAppearance(symbolId) {
  if (!Number.isInteger(symbolId)) { cache.clear(); return; }
  for (const key of cache.keys()) if (key.startsWith(`${symbolId}:`)) cache.delete(key);
}
